/* ==== HUB-LIB BEGIN (由 build.mjs 生成，勿手改) ==== */
/* 本块由 build.mjs 生成。想改请改仓库 libs/ 下的源文件，然后重跑构建。 */
/* ============================================================================
 * hub.js —— 书源中枢运行时（Rhino / 阅读 jsLib 兼容）
 * ----------------------------------------------------------------------------
 * 这段代码有两个宿主：
 *   1) 阅读 App 的 Rhino 引擎（真机）：通过 jsLib 里的 HUB 对象调用
 *   2) Node（本地自检 / 模拟器）：tools/simulate.mjs 直接 eval
 *
 * 因此这里 **只用** ES5 + 少量被两个引擎都支持的语法（let / 模板串 / 箭头函数
 * 在 Rhino 6+ 与 Node 都可用；但为稳妥，本文件刻意用 var + 函数声明）。
 *
 * 注入约定：
 *   createHub(java, source, opts)
 *     java   —— 宿主 java 对象（阅读内置），mock 里是实现同一批方法的桩
 *     source —— 当前 Source（提供 getVariable/setVariable/cache）
 *     opts   —— { mirrors:[], cacheTTL:int, log:fn, now:fn }
 *
 * 产物 JSON 的"消费方"约定（供 main.js 用）：
 *   manifest = { schema, version, updated, bookSources:[{key,name,group,enabled,type,desc,file,sha256,lastUpdateTime,deprecated}], rss:[...], libs:[...] }
 * ==========================================================================*/
/* 书源的 jsLib 是在"静态上下文"里跑的，那时通常没有 java/source。
 * 所以 createHub 允许先建壳、后绑定：调用 createHub() 之后立刻 .bind(java, source)，
 * 或者由 HUBCTX 里的 onCall 每次调用时自动刷新绑定。 */
function createHub(java, source, opts) {
    opts = opts || {};
    var MIRRORS = opts.mirrors && opts.mirrors.length ? opts.mirrors : ['', 'https://ghproxy.net/', 'https://gh-proxy.com/'];
    var CACHE_TTL = opts.cacheTTL || 21600;      // 秒；0 = 永久
    var CACHE_PREFIX = 'hub:';
    var ST_LASTOK = 'hub:lastok';                // 上次成功的镜像序号

    function nowMs() { return opts.now ? opts.now() : new Date().getTime(); }
    function log(m) { if (opts.log) opts.log(String(m)); }

    /* ---------- 缓存（CacheManager，存在 App 私有目录，重启不丢） ---------- */
    function cacheGet(key) {
        try { return source.cache.get(CACHE_PREFIX + key) || ''; } catch (e) { return ''; }
    }
    function cachePut(key, val, ttl) {
        try { source.cache.put(CACHE_PREFIX + key, String(val), ttl === undefined ? CACHE_TTL : ttl); } catch (e) { }
    }

    /* ---------- 多镜像取文件：按上次成功的镜像优先，失败自动降级 ---------- */
    function fetchText(path, useCache) {
        var cacheKey = 'file:' + path;
        if (useCache !== false) {
            var c = cacheGet(cacheKey);
            if (c) return c;
        }
        var start = 0;
        try { var li = parseInt(cacheGet(ST_LASTOK), 10); if (li >= 0 && li < MIRRORS.length) start = li; } catch (e) { }
        var errs = [];
        for (var n = 0; n < MIRRORS.length; n++) {
            var i = (start + n) % MIRRORS.length;
            var url = MIRRORS[i] + path + '?t=' + nowMs();      // t= 破镜像缓存
            try {
                var res = java.get(url, { 'User-Agent': 'Legado-Hub/2.0' });
                var code = res.status ? res.status() : 200;
                if (code === 200) {
                    var body = res.body();
                    if (body && body.length) {
                        cachePut(ST_LASTOK, String(i), 0);
                        cachePut(cacheKey, body, CACHE_TTL);
                        return body;
                    }
                }
                errs.push('#' + i + ' HTTP ' + code);
            } catch (e) {
                errs.push('#' + i + ' ' + e);
            }
        }
        throw new Error('全部镜像失败：' + errs.join(' | '));
    }

    function fetchJson(path, useCache) { return JSON.parse(fetchText(path, useCache)); }

    /* ---------- 版本比较：语义化 + lastUpdateTime ---------- */
    function cmpVer(a, b) {
        a = String(a || '0'); b = String(b || '0');
        if (/^\d+$/.test(a) && /^\d+$/.test(b)) return Number(a) - Number(b);
        var pa = a.split(/[.\-+]/), pb = b.split(/[.\-+]/);
        for (var i = 0; i < Math.max(pa.length, pb.length); i++) {
            var x = parseInt(pa[i] || '0', 10), y = parseInt(pb[i] || '0', 10);
            if (x > y) return 1;
            if (x < y) return -1;
        }
        return a.localeCompare(b);
    }

    /* ---------- 用户配置（只认这几种 key，永远不整体覆盖） ---------- */
    var CONFIG_KEYS = ['hub', 'libs', 'policy', 'mirror', 'lastSeenVersion', 'localVersion'];

    function getCfg() {
        var s = '';
        try { s = String(source.getVariable() || ''); } catch (e) { s = ''; }
        if (!s) return {};
        try { return JSON.parse(s) || {}; } catch (e) { return {}; }
    }
    function setCfg(cfg) {
        var keep = {};
        for (var i = 0; i < CONFIG_KEYS.length; i++) {
            var k = CONFIG_KEYS[i];
            if (cfg[k] !== undefined) keep[k] = cfg[k];
        }
        try { source.setVariable(JSON.stringify(keep, null, '\t')); } catch (e) { }
        return keep;
    }
    // 迁移：老版订阅源变量里有 sourl/jk/type/seturl/key/name/page —— 原样保留，别弄丢用户密钥
    function migrateCfg() {
        var cfg = getCfg();
        var dirty = false;
        var legacy = ['sourl', 'jk', 'type', 'seturl', 'key', 'name', 'page'];
        for (var i = 0; i < legacy.length; i++) {
            var k = legacy[i];
            if (cfg[k] !== undefined) { delete cfg[k]; dirty = true; }
        }
        if (cfg.hub === undefined) { cfg.hub = 2; dirty = true; }
        if (dirty) setCfg(cfg);
        // 老字段另存一份，万一下游还要用
        return cfg;
    }

    /* ---------- 打包：把多份书源 JSON 合成一份"可导入"的文件 ---------- */
    function pack(list) {
        var arr = [];
        for (var i = 0; i < list.length; i++) {
            var it = list[i];
            if (!it) continue;
            arr = arr.concat(Array.isArray(it) ? it : [it]);
        }
        return JSON.stringify(arr, null, 2);
    }

    /* ---------- 深链：两种都可用，native 优先 ---------- */
    function deepLink(kind, url) {
        return 'legado://import/' + kind + '?src=' + encodeURIComponent(url);
    }
    function nativeImport(kind, url) {
        // java.openUrl 对 legado:// 会直接拉起 OnLineImportActivity（源码已核实）
        try {
            java.openUrl(deepLink(kind, url));
            return true;
        } catch (e) {
            log('openUrl 失败，回退 startBrowser：' + e);
            try { java.startBrowser(deepLink(kind, url), '导入'); return true; } catch (e2) { return false; }
        }
    }

    var _bound = !!(java && source);
    function bind(j, s) {
        if (j) java = j;
        if (s) source = s;
        if (j || s) _bound = true;
    }
    function ready() {
        if (!_bound) throw new Error('createHub 尚未绑定宿主：请在规则里调 HUB.bind(java, source) 后使用');
        return true;
    }

    // 统一入口：调用前确保已绑定
    function wrap(fn) {
        return function () {
            try { ready(); } catch (e) { if (opts.onError) return opts.onError(e); throw e; }
            return fn.apply(null, arguments);
        };
    }
    return {
        bind: bind,
        _ready: ready,
        MIRRORS: MIRRORS,
        CACHE_TTL: CACHE_TTL,
        nowMs: nowMs,
        log: log,
        cacheGet: cacheGet,
        cachePut: cachePut,
        fetchText: wrap(fetchText),
        fetchJson: wrap(fetchJson),
        cmpVer: cmpVer,
        getCfg: wrap(getCfg),
        setCfg: wrap(setCfg),
        migrateCfg: migrateCfg,
        pack: pack,
        deepLink: deepLink,
        nativeImport: nativeImport
    };
}

/* ============================================================================
 * hotload.js —— 书源「热更新」运行时（C 档）
 * ----------------------------------------------------------------------------
 * 目标：书源本体（规则、选择器、密钥流程）一旦装好就基本不动；
 *       真正的抓取逻辑放进仓库里的 lib-<key>.js，运行时拉取并缓存。
 *       以后改解析逻辑 = 改仓库一个文件，所有装了该源的人下次请求自动生效。
 *
 * 用法（书源 jsLib 最前面）：
 *     var HS = createHot({ key:'<书源key>', base:'legado-sources/', mirrors:[...] });
 *     var L  = HS.lib();            // 拿到远程 lib 导出的对象
 *     L.search(java, source, key, page)
 *
 * 安全网（非常重要）：
 *   1) 远程代码可能拉到半截 / 拉到 HTML 错误页 —— 先做语法与结构校验
 *   2) 新代码 eval/执行抛错 —— 尝试回滚到上一份可用缓存
 *   3) 全挂 —— 抛错，让阅读显示失败，绝不静默返回空结果
 * ==========================================================================*/
function createHot(opts) {
    opts = opts || {};
    var KEY = opts.key || 'unknown';
    var BASE = opts.base || '';
    var MIRRORS = opts.mirrors && opts.mirrors.length ? opts.mirrors : ['', 'https://ghproxy.net/', 'https://gh-proxy.com/'];
    var TTL = opts.ttl === undefined ? 3600 : opts.ttl;
    var LIBFILE = opts.lib || ('libs/lib-' + KEY + '.js');
    var PREV = 'hot:' + KEY + ':prev';      // 上一份可用的完整源码
    var CUR = 'hot:' + KEY + ':code';

    // 宿主绑定：
    //   规则里调用 → 直接拿到阅读注入的 java / source（每次执行都会注入）
    //   jsLib 静态上下文里调用 → 可能是 undefined，之后用 bind() 补上
    var g = {};
    if (opts.java) g.java = opts.java;
    if (opts.source) g.source = opts.source;
    (function () {
        // 闭包里能拿到 createHot 被调用处作用域的 java/source（Rhino 与 Node 都是这样）
        try { if (!g.java && typeof java !== 'undefined' && java) g.java = java; } catch (e) { }
        try { if (!g.source && typeof source !== 'undefined' && source) g.source = source; } catch (e) { }
    })();

    function cacheGet(k) { try { return g.source.cache.get(k) || ''; } catch (e) { return ''; } }
    function cachePut(k, v, ttl) { try { g.source.cache.put(k, v, ttl === undefined ? TTL : ttl); } catch (e) { } }

    /* ---------- 拉远程源码（多镜像 + 破缓存） ---------- */
    function remote(force) {
        var u;
        var errs = [];
        for (var i = 0; i < MIRRORS.length; i++) {
            u = MIRRORS[i] + BASE + LIBFILE + (force ? ('?t=' + new Date().getTime()) : '');
            try {
                var r = g.java.get(u, { 'User-Agent': 'Legado-Hub/2.0' });
                if ((r.status ? r.status() : 200) === 200) {
                    var b = r.body() || '';
                    // 只挡明显的坏响应（错误页 / 空壳）；真正的判定交给 compile()
                    var looksBad = b.length < 20
                        || /^\s*</.test(b)                       // HTML 错误页
                        || /^(404|not found|Bad Gateway)/i.test(b);
                    if (!looksBad) return b;
                    errs.push('#' + i + ' 内容异常(' + b.length + 'B)');
                } else {
                    errs.push('#' + i + ' HTTP ' + (r.status ? r.status() : '?'));
                }
            } catch (e) { errs.push('#' + i + ' ' + e); }
        }
        throw new Error('lib 拉取失败 ' + LIBFILE + ' :: ' + errs.join(' | '));
    }

    /* ---------- 校验：能解析、能执行、导出了 lib 对象 ---------- */
    function compile(code) {
        // 在 Rhino 里 new Function 可用；Node 同样。只用它做"语法+执行"双检。
        var f = new Function('java', 'source', code + '\n;return typeof lib!=="undefined"?lib:null;');
        var out = f(g.java, g.source);
        if (!out || typeof out !== 'object') throw new Error('lib 未导出对象');
        return out;
    }

    var _lib = null;
    var _src = '';
    var _bound = false;          // 是否已绑定宿主（书源 jsLib 里静态创建时为 false）

    function bind(j, s) {
        if (j) g.java = j;
        if (s) g.source = s;
        if (!_bound) { _bound = true; _lib = null; }   // 换宿主 → 缓存必须重编译
    }

    function lib(force) {
        // 每次调用都刷新绑定：规则执行时 java/source 是当前的，不会拿到旧会话
        try { if (typeof java !== 'undefined' && java) bind(java, null); } catch (e) { }
        try { if (typeof source !== 'undefined' && source) bind(null, source); } catch (e) { }
        if (!_bound) throw new Error('热更新模块未绑定宿主（java/source）');
        if (_lib && !force) return _lib;

        var cached = cacheGet(CUR);
        // 1) 先试缓存（秒开，离线也能用）
        if (cached && !force) {
            try { _lib = compile(cached); _src = 'cache'; return _lib; } catch (e) { }
        }
        // 2) 拉远程
        var code = null;
        try { code = remote(force); } catch (e) {
            if (cached) { _lib = compile(cached); _src = 'cache-fallback'; return _lib; }
            throw e;
        }
        // 3) 编译；失败则回滚上一份
        try {
            _lib = compile(code);
            if (cached && cached !== code) cachePut(PREV, cached, 0);
            cachePut(CUR, code, TTL);
            _src = 'remote';
            return _lib;
        } catch (e) {
            if (cached) {
                try { _lib = compile(cached); _src = 'cache-after-badremote'; return _lib; } catch (e2) { }
            }
            var prev = cacheGet(PREV);
            if (prev) {
                _lib = compile(prev);
                _src = 'prev';
                return _lib;
            }
            throw new Error('远程 lib 不可用，且无可用缓存：' + e);
        }
    }

    /* ---------- 带兜底地执行一个方法 ---------- */
    function call(name) {
        var args = Array.prototype.slice.call(arguments, 1);
        var l = lib(false);
        if (typeof l[name] !== 'function') throw new Error('lib 缺少方法 ' + name);
        try {
            return l[name].apply(l, args);
        } catch (e) {
            // 可能是新代码坏了：强制重取一次（若还是坏，上一份缓存已在编译阶段回滚）
            var l2 = lib(true);
            if (l2 === l) throw e;
            return l2[name].apply(l2, args);
        }
    }

    /* ---------- 版本信息（调试用） ---------- */
    function info() {
        return { key: KEY, file: LIBFILE, source: _src, mirrors: MIRRORS, ttl: TTL };
    }

    return { lib: lib, call: call, info: info, bind: bind, _set: bind };
}

/* --- 该源的远程逻辑入口（C 档热更新：改仓库 libs/lib-jenshimanhua.js 即可生效） --- */
var HSRC = { key: "jenshimanhua", base: "https://raw.githubusercontent.com/GEd520/legado-sources/main/", mirrors: ["","https://ghproxy.net/","https://gh-proxy.com/"] };
var HOT = createHot({ key: HSRC.key, base: HSRC.base, mirrors: HSRC.mirrors, lib: 'dist/libs/lib-jenshimanhua.js' });
/* 拿到远程逻辑对象；失败时返回 null，规则里要自己判空并走本地兜底 */
function hotLib() { try { return HOT.lib(false); } catch (e) { try { java.log('hotLib 不可用: ' + e); } catch (e2) { } return null; } }
/* ============================================================================
 * gate.js —— 书源门禁客户端 v3（跑在阅读 App 的 Rhino 里）
 * ----------------------------------------------------------------------------
 * 核心约束（均在 Legado_Max 源码 + Rhino 1.7.14 实测确认）
 *   1. jsLib 求值时**没有** java / source —— 顶层绝不能引用它们
 *   2. jsLib 函数里的裸标识符 source 解析失败，只能走 this.source
 *      （这就是原书源都写 this.java 的原因）
 *   3. jsLib 函数里直接调另一个 jsLib 函数，this 会退化成 Java 包对象
 *   4. new Function 建在全局作用域，看不到 jsLib / java / source
 *   5. Rhino 无 Proxy，无法自动代理
 *
 * 因此 lib 的加载方式是：把服务端下发的**源码字符串**交给该执行器，
 * 由它在一个「还原了 jsLib 上下文」的作用域里 eval —— 语义与直接写在
 * 规则里完全一致（原书源那套 getUrl()/cache/source 都不需要改）。
 *
 * 安全模型（v3 变更）
 *   ✗ 不再在书源里放任何共享密钥。客户端是公开分发的，放密钥等于公开密钥；
 *     且有了密钥反而能伪造任意 uid、冒充他人设备。
 *   ✓ 设备身份 = androidId 派生的稳定 did，服务端按 did 下发「专属密文」，
 *     可精确封禁/吊销/溯源。
 *   ✓ 传输层再加时间戳窗口 + 服务端限流，挡住最粗糙的批量脚本。
 * ==========================================================================*/
function createGate(java, source, cfg) {
    cfg = cfg || {};

    /* ---------------- 端点（多线路自动降级） ---------------- */
    var URLS = [];
    (function () {
        var raw = cfg.urls || cfg.url || '';
        if (typeof raw === 'string') raw = [raw];
        for (var i = 0; i < (raw || []).length; i++) {
            if (raw[i]) URLS.push(String(raw[i]).replace(/\/+$/, ''));
        }
        var fb = cfg.fallback;
        if (typeof fb === 'string') fb = [fb];
        for (var j = 0; j < (fb || []).length; j++) {
            var u = String(fb[j] || '').replace(/\/+$/, '');
            if (u && URLS.indexOf(u) < 0) URLS.push(u);
        }
        if (!URLS.length) throw new Error('门禁未配置地址');
    })();

    var KID = cfg.kid || '';
    var TTL_DEFAULT = cfg.ttl || 21600;
    var CK_CODE = 'gate:' + KID + ':code';
    var CK_TS = 'gate:' + KID + ':ts';

    function log(m) { try { java.log('[gate] ' + m); } catch (e) { } }

    /* ---------------- 设备标识 ---------------- */
    var _did = null;
    function did() {
        if (_did) return _did;
        var raw = '';
        try { raw = String(java.androidId() || ''); } catch (e) { }
        if (!raw || raw === 'null' || raw === 'undefined') {
            // 兜底：设备信息 + 来源 key 的哈希，保证同一台机器稳定
            try {
                raw = 'fb|' + String(java.getWebViewUA() || '') + '|' + String(cfg.origin || '');
                raw = String(java.md5Encode(raw));
            } catch (e2) { raw = 'fb|anon'; }
        }
        var h = raw;
        // 不直接把 androidId 明文发出去
        try { h = String(java.md5Encode('legado-gate|' + raw)); } catch (e3) { }
        _did = 'd' + h.replace(/[^0-9a-zA-Z]/g, '').slice(0, 40);
        return _did;
    }

    /* ---------------- 设备令牌（可选） ----------------
     * 服务端开启「需登记」后，用户从作者发布页拿到 token 填进登录界面，
     * 这里读出并随请求带上。没 token 也能跑（首次使用自动放行）。
     */
    var CK_TOKEN = 'gate:' + KID + ':token';
    function getToken() {
        try {
            var a = String(cfg.token || '');
            if (a) return a;
        } catch (e) { }
        try { return cGet(CK_TOKEN) || ''; } catch (e2) { return ''; }
    }
    function setToken(t) {
        cfg.token = String(t || '');
        try { cPut(CK_TOKEN, cfg.token, 86400 * 365); } catch (e) { }
    }

