function login(b) {
  if (b == undefined) return true;
  info = result
  so = getUrl();
  pw = info.密码

  if (b) {
    let name = result["用户名/邮箱"];
    if (name == "") {
        java.toast("\n账号密码不能为空！");
        return false;
    };
    url = so + '/users-check_login.html'
    body = `normal=1&login_name=${encodeURI(info["用户名/邮箱"])}&login_pass=${pw}`
  } else {
    java.startBrowser('{{getUrl()}}/users-reg.html','注册');
    return false;
  }
  post = JSON.stringify({
    "body": String(body),
    "method": "POST",
    "headers":{
    "User-Agent":java.getWebViewUA(),
    "Origin": getUrl(),
    "Referer": getUrl() + "/users-login.html"
    }
  })
  try {
    resp = java.connect(url + ',' + post); 
    result =resp.body();
  } catch (error) {
    java.log('💔访问出错💔');
    java.toast('\n💔访问出错，请换接口💔');
  }
  if(result.match(/true/)){
    //java.log(url) 
    java.toast(info["用户名/邮箱"] + ' 登录成功');
var ck=resp.headers().get("Set-Cookie");
//java.log(ck);
if (ck) {
   cookie.setCookie(so, ck);
   source.putLoginHeader(ck);
   };
   }else{
  	java.toast("\n" + ' 登录失败');
  	}
}

